var QUESTOES_CONCORDANCIA = [{"id":801,"enunciado":"Analise as afirmações que seguem e assinale a que apresenta uma afirmação correta:","opcoes":["A palavra \"sussurro\" tem como antônimo \"murmúrio\", enquanto \"dependência\" possui como sinônimo \"subordinação\".","Todas as frases do texto são declarativas afirmativas e estão corretamente escritas.","Nas palavras \"maravilhosa\", \"esquecer\" e \"justamente\" temos exemplos de dígrafos.","A frase \"É talvez chegar em casa e contar seu dia e só sentir que teve um dia quando a gente conta como foi\" possui um erro de concordância verbal.","O segundo período do texto está escrito em linguagem culta e sem erros de ortografia."],"correta":2,"explicacao":"Gabarito: <strong>Nas palavras \"maravilhosa\", \"esquecer\" e \"justamente\" temos exemplos de dígrafos.</strong>.","banca":"AMAUC","ano":2025,"temas_relacionados":["concordancia","digrafos"]},{"id":1721,"enunciado":"\"Ao minimizar os \"picos\" de dopamina a curto prazo, que pode vir de redes sociais, jogos ou de acumular muitas tarefas ao mesmo tempo, você pode reconstruír sua capacidade de fazer um trabalho profundo e retomar o controle da sua atenção.\" O período apresenta erros relacionados:","opcoes":["à ortografia e a concordância nominal.","ao emprego da crase e à concordância nominal.","à concordância nominal e à verbal.","à acentuação e à concordância verbal."],"correta":3,"explicacao":"Gabarito: <strong>à acentuação e à concordância verbal.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["concordancia"]},{"id":3156,"enunciado":"Assinale a alternativa que atende à norma-padrão de concordância verbal, de regência e de colocação pronominal.","opcoes":["A universidade e o mundo todo lembrarão de Stephen Hawking, o que é coerente ao seu perfil inspirador.","Se lembrará a universidade e o mundo todo de Stephen Hawking, o que é coerente perante o seu perfil inspirador.","A universidade e o mundo todo lembrar-se-ão de Stephen Hawking, o que é coerente com o seu perfil inspirador.","Lembrarão-se de Stephen Hawking a universidade e o mundo todo, o que é coerente sobre o seu perfil inspirador.","A universidade e o mundo todo se lembrará de Stephen Hawking, o que é coerente do seu perfil inspirador."],"correta":2,"explicacao":"Gabarito: <strong>A universidade e o mundo todo lembrar-se-ão de Stephen Hawking, o que é coerente com o seu perfil inspirador.</strong>.","banca":"VUNESP","ano":2025,"temas_relacionados":["concordancia"]},{"id":3266,"enunciado":"No texto “Caso de secretária”, de Carlos Drummond de Andrade, observe a frase: “Teve vontade de mandar todos embora, para que todos comemorassem o seu aniversário, ele principalmente.” Assinale a alternativa que apresenta a análise correta em termos de concordância nominal e verbal, regência e colocação pronominal:","opcoes":["A frase está correta em termos de concordância nominal e verbal, regência e colocação pronominal, mantendo a clareza no sentido.","A concordância nominal está incorreta, pois “todos” deveria concordar com “ele” em gênero e número.","A regência do verbo “mandar” está incorreta, pois deveria ser acompanhada de preposição: “mandar a todos embora”.","A colocação pronominal está incorreta, pois “se” deveria vir antes do verbo em “ele se principalmente”.","A expressão “ele principalmente” está deslocada na ordem das palavras, causando ambiguidade na frase."],"correta":0,"explicacao":"Gabarito: <strong>A frase está correta em termos de concordância nominal e verbal, regência e colocação pronominal, mantendo a clareza no sentido.</strong>.","banca":"UFCG","ano":2025,"temas_relacionados":["concordancia"]},{"id":3540,"enunciado":"O título do item 3 do texto 2, “Se vista para o sucesso”, apresenta uma ocorrência que, embora não seja aceita pela gramática tradicional, é muito comum na linguagem oral, mesmo na variedade culta da língua. Essa ocorrência encontra-se na","opcoes":["concordância verbal.","flexão nominal.","regência nominal.","silepse de número.","colocação pronominal."],"correta":4,"explicacao":"Gabarito: <strong>colocação pronominal.</strong>.","banca":"COSEAC","ano":2024,"temas_relacionados":["concordancia"]},{"id":3627,"enunciado":"Assinale a alternativa que atende à norma-padrão de concordância verbal, de emprego de pronome e de colocação pronominal.","opcoes":["No teatro grego antigo, quando surgia os impasses, um ator interpretando uma divindade descia ao palco pendurado num guindaste e resolvia-os.","De acordo com especialistas, porém, o perigo não está nas criaturas que vem sendo criadas e, sim, na forma como os criadores usam-as.","Ainda que não se perceba, há vários exemplos do dia a dia que mostra como a inteligência artificial vem influenciando-o bastante.","Um grupo de cientistas pediram a moratória de pesquisas até alguma regulamentação ética da IA, talvez porque a IA lhes inquietou.","Um dos que não acredita que a Inteligência Artificial ultrapassará o homem em astúcia é Ganascia, que a estuda há vários anos em Paris."],"correta":4,"explicacao":"Gabarito: <strong>Um dos que não acredita que a Inteligência Artificial ultrapassará o homem em astúcia é Ganascia, que a estuda há vários anos em Paris.</strong>.","banca":"VUNESP","ano":2023,"temas_relacionados":["concordancia"]},{"id":3653,"enunciado":"Em qual dos trechos a seguir as regras de concordância, regência ou colocação foram empregadas de acordo com a norma padrão da língua portuguesa?","opcoes":["Taylor Swift é influenciada pela mãe e já foi proibida de vim ao Brasil","Quem compra aparelhos hoje, pode ter de esperar semanas pela instalação","WhatsApp vai avisar quando uma foto não poder ser enviada em HD","Quando você vê-la, me avise para que possamos conversar.","Viúva do criador de 'Chaves' quebra silêncio sobre apagão da série na TV: 'Não foi eu que disse não'"],"correta":1,"explicacao":"Gabarito: <strong>Quem compra aparelhos hoje, pode ter de esperar semanas pela instalação</strong>.","banca":"Instituto Darwin","ano":2023,"temas_relacionados":["concordancia"]},{"id":3855,"enunciado":"“É objeto da sintaxe o estudo das palavras associadas na frase. Examina: a função das palavras e das orações no período (análise sintática); as relações de dependência das palavras na oração, sob o aspecto de subordinação (sintaxe de regência); as relações de dependência das palavras consideradas do ponto de vista da flexão (sintaxe de concordância) e a disposição ou ordem das palavras e das orações no período (sintaxe de colocação).\" (CEGALLA, D. Paschoal. Novíssima gramática da língua portuguesa. São Paulo: Companhia Editora Nacional: 2010, p. 18.) Em sintonia com os conceitos apresentados pelo gramático, leia os textos a seguir. TEXTO I “Atualmente, muito se preconiza quanto à humanização da saúde. O legado de Pedro Bloch não pode figurar fora desses ensinamentos. Além de ele próprio ouvir os pacientes miúdos, recolhendo matéria -prima para seus estudos e textos, dava voz à meninada, reproduzindo suas histórias.” (3º§) TExTO II Disponível em: https://mamaepratica.com.br/2015/04/26/perolas-das-criancas-transformadas-em-tirinhas/ Com base nos aspectos gramaticais analisados nos dois textos, é correto afirmar que a","opcoes":["forma verbal “ouvir”, nos dois textos, quanto à sua transitividade, é classificada, no contexto em que foi empregada, como sendo transitiva indireta.","crase em “Ás vezes é bom conversar comigo mesmo!” (Texto II) está corretamente escrita, pois a norma determina utilizar o acento grave para grafá-la.","vírgula é desnecessária em “Tá falando com quem filho!?\" (Texto II), porque não existe regra gramatical indicativa de que, nesse caso, ela deve ser empregada.","frase “O legado de Pedro Bloch não pode figurar fora desses ensinamentos.” apresenta um erro de concordância verbal, pois, na oração, o núcleo do sujeito exige verbo no plural.","próclise é de rigor na frase “Atualmente, muito se preconiza quanto à humanização da saúde” (Texto I) porque antes do verbo, na oração, há palavra que atrai o pronome átono."],"correta":4,"explicacao":"Gabarito: <strong>próclise é de rigor na frase “Atualmente, muito se preconiza quanto à humanização da saúde” (Texto I) porque antes do verbo, na oração, há palavra que atrai o pronome átono.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["concordancia"]},{"id":3957,"enunciado":"Assinale a alternativa que apresenta a frase de forma CORRETA:","opcoes":["O atriz recebeu aplausos.","As cidadão participaram da reunião.","Os rapaz chegaram cedo.","As meninas estavam animadas.","O professoras organizaram a atividade."],"correta":3,"explicacao":"Gabarito: <strong>As meninas estavam animadas.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["concordancia"]},{"id":4099,"enunciado":"Leia a tirinha:(Jim Davis. Garfield numa boa. Porto Alegre: E&PM, 2007)Assinale a alternativa que completa, correta e respectivamente, as lacunas dos quadrinhos.","opcoes":["escravos ... serão ... tem","escravo ... será ... temos","escravos ... serão ... terão","escravo ... serão ... tem"],"correta":0,"explicacao":"Gabarito: <strong>escravos ... serão ... tem</strong>.","banca":"Diretoria de Ensino de Andradina - SP","ano":2025,"temas_relacionados":["concordancia"]},{"id":4982,"enunciado":"Assinale a alternativa que apresenta erro de concordância verbal, de acordo com a gramática.","opcoes":["Muito obrigadas! – Disseram as mulheres da empresa.","Sr. Deputado, V.Exa. está enganado.","A casa estava meio bagunçada.","O elenco era muito comprometido.","Construiu-se novas escolas."],"correta":4,"explicacao":"Gabarito: <strong>Construiu-se novas escolas.</strong>.","banca":"Unoesc","ano":2024,"temas_relacionados":["concordancia"]},{"id":5155,"enunciado":"Observe a concordância nominal entre o substantivo “setores” e os adjetivos “público e privado” em: “[...] é fundamental um esforço coordenado entre os setores público e privado, juntamente com organizações de catadores.” (12º§) Assinale a alternativa cuja concordância nominal está INCORRETA.","opcoes":["O homem apresentava expressão e figurino delicado.","Os alunos já encerraram o primeiro e o segundo períodos.","O médico disse que vitamina é boa para a minha recuperação.","O público ficou entusiasmado com a música italiana e a portuguesa."],"correta":2,"explicacao":"Gabarito: <strong>O médico disse que vitamina é boa para a minha recuperação.</strong>.","banca":"Instituto Consulplan","ano":2024,"temas_relacionados":["concordancia"]},{"id":5334,"enunciado":"Em Com a nova legislação, fica proibida a autodeclaração de maioridade, a concordância nominal segue a norma-padrão da língua em função da presença do artigo definido. Considerando isso, assinale a alternativa em que a concordância nominal apresenta erro.","opcoes":["É obrigatória a adoção de medidas de segurança pelas empresas responsáveis pelas plataformas digitais.","Foi autorizada a utilização de mecanismos tecnológicos para a verificação etária nas plataformas digitais.","É proibido a divulgação de dados pessoais de crianças e adolescentes nas redes sociais.","É necessário atuação constante da escola na promoção do letramento digital."],"correta":2,"explicacao":"Gabarito: <strong>É proibido a divulgação de dados pessoais de crianças e adolescentes nas redes sociais.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["concordancia"]},{"id":5634,"enunciado":"Se trocarmos o artigo “os”, sublinhado no primeiro parágrafo, pelo artigo “as”, quantas outras palavras deverão ser modificadas para que a concordância esteja CORRETA?","opcoes":["Nenhuma.","Uma.","Duas.","Três."],"correta":2,"explicacao":"Gabarito: <strong>Duas.</strong>.","banca":"OBJETIVA","ano":2023,"temas_relacionados":["concordancia"]},{"id":5879,"enunciado":"Considere as três formas verbais elencadas na coluna da esquerda; e, na da direita, as respectivas justificativas em relação à concordância verbal. Quais justificativas estão corretas?","opcoes":["Apenas 1.","Apenas 2.","Apenas 1 e 3.","Apenas 2 e 3.","1, 2 e 3."],"correta":2,"explicacao":"Gabarito: <strong>Apenas 1 e 3.</strong>.","banca":"MPE-RS","ano":2021,"temas_relacionados":["concordancia"]},{"id":6206,"enunciado":"Sobre concordância nominal, assinalar a alternativa cujos elementos preenchem CORRETAMENTE as lacunas. I. As professoras enviaram os atestados das suas faltas, _________ às procurações, para não sofrerem descontos. II. __________ a mulher e o homem estão neste mundo. III. Naquele mercantil, comprei melão e melancia ________. IV. Não consigo imaginar ________ milhares de crianças nas ruas.","opcoes":["anexos | Cansados | estragados | aqueles","anexas | Cansada | estragados | aqueles","anexos | Cansados | estragadas | aquelas","anexas | Cansada | estragada | aquelas"],"correta":0,"explicacao":"Gabarito: <strong>anexos | Cansados | estragados | aqueles</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["concordancia"]},{"id":6215,"enunciado":"Leia o trecho e considere as lacunas a seguir: “Após o evento, os participantes expressaram opiniões __________ e sugestões __________ sobre as palestras ministradas.” Agora, assinale a alternativa que preenche CORRETAMENTE as lacunas acima, considerando a concordância nominal:","opcoes":["Divergentes – construtivas.","Divergente – construtivo.","Divergentes – construtivo.","Divergente – construtivas."],"correta":0,"explicacao":"Gabarito: <strong>Divergentes – construtivas.</strong>.","banca":"CONSULPAM","ano":2026,"temas_relacionados":["concordancia"]},{"id":6236,"enunciado":"Considerando as normas de concordância nominal, assinalar a alternativa INCORRETA.","opcoes":["É necessário saúde para estar vivo.","Martin tinha dons e habilidades extraordinários.","Fiquem alertas ao passar por essa rua de noite.","Estamos quites já que você me pagou a dívida."],"correta":2,"explicacao":"Gabarito: <strong>Fiquem alertas ao passar por essa rua de noite.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["concordancia"]},{"id":6253,"enunciado":"Assinale a opção em que a concordância nominal está de acordo com a modalidade padrão.","opcoes":["Este cronista, brilhantemente, usou metáforas o mais criativas possível.","Anexo, esse livro contém uma tabela periódica dos elementos químicos.","É indispensável, em qualquer fase da vida, as palavras carinhosas e amigas.","Cuidadosamente, acompanhe cada etapa do concurso estadual e municipal.","A literatura é patrimônio do mundo porque sempre traz alguma coisa de boa."],"correta":0,"explicacao":"Gabarito: <strong>Este cronista, brilhantemente, usou metáforas o mais criativas possível.</strong>.","banca":"Marinha","ano":2026,"temas_relacionados":["concordancia"]},{"id":6258,"enunciado":"Assinale a alternativa que apresenta concordância nominal de forma CORRETA:","opcoes":["Seguem anexo os documentos solicitados.","Segue anexas as fotografias do evento.","Seguem anexos os documentos solicitados.","Segue anexo as fotografias do evento.","Seguem anexa a documentação necessária."],"correta":2,"explicacao":"Gabarito: <strong>Seguem anexos os documentos solicitados.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["concordancia"]},{"id":6276,"enunciado":"Analise o trecho a seguir, à luz das normas da gramática culta referentes à concordância nominal. “Durante a inspeção, constatou-se que as salas estavam _____ limpas, as normas eram _____ claras para todos, e as atas seguem _____ ao processo administrativo. Os servidores permaneceram _____ após o expediente.” Com base nas regras de concordância nominal, assinale a alternativa que preenche corretamente as lacunas, na ordem em que aparecem no texto.","opcoes":["meio − bastante − anexas − sós","meios − bastantes − anexas − sós","meios − bastante − anexos − só","meio − bastantes − anexos – só"],"correta":0,"explicacao":"Gabarito: <strong>meio − bastante − anexas − sós</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["concordancia"]},{"id":6279,"enunciado":"Marque a alternativa em que a palavra destacada apresenta concordância correta.","opcoes":["Apavorados, as alunas foram parar na diretoria da escola.","Os habitantes da cidade ficaram muito impressionado com o nosso tratamento.","Maria, assim que você estiver liberado peço que me avise.","Minha mãe e Antônio estão muito ansiosos para saber o resultado da prova.","Esses produtos são totalmente livre de glúten."],"correta":3,"explicacao":"Gabarito: <strong>Minha mãe e Antônio estão muito ansiosos para saber o resultado da prova.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6282,"enunciado":"No trecho a seguir, retirado do texto, se a palavra “astronautas” fosse flexionada no singular, quantas outras alterações seriam obrigatoriamente necessárias para manter a correta concordância no excerto? “Nunca ninguém foi tão distante da Terra como esses astronautas. Eu os conheci e são simpáticos, humildes e, claro, extremamente competentes”.","opcoes":["Três.","Quatro.","Cinco.","Seis."],"correta":3,"explicacao":"Gabarito: <strong>Seis.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6295,"enunciado":"\"Como não existem populações selvagens dessas aves na Mata Atlântica, eles são criados em cativeiro, vindos de adoções ou apreensões realizadas em combate ao tráfico de animais.\" Considerando a concordância verbal e nominal, marque com V as afirmativas verdadeiras ou com F as falsas. (__)O verbo 'existir' pode ser substituído pelo verbo 'haver' desde que a construção resultante mantenha o verbo flexionado no singular, uma vez que ambos os verbos compartilham o caráter impessoal quando empregados no sentido de 'existência'. (__)O particípio 'criados' concorda em gênero e número com o pronome 'eles', sujeito da oração, seguindo a regra geral de concordância nominal do particípio em construções passivas, em que o particípio funciona como predicativo do sujeito. (__)O adjetivo 'selvagens' concorda em gênero e número com o núcleo do sintagma nominal 'populações', no plural, seguindo a regra geral de concordância nominal, em que o adjetivo flexiona de acordo com o substantivo a que se refere. (__)O verbo 'existir', verbo pessoal, concorda com o núcleo do sujeito 'populações' no plural, sendo incorreta a flexão no singular, uma vez que, diferentemente do verbo 'haver', não possui caráter impessoal e invariável. Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["F, V, F, V.","V, V, F, F.","F, V, V, V.","V, F, V, F."],"correta":2,"explicacao":"Gabarito: <strong>F, V, V, V.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["concordancia"]},{"id":6311,"enunciado":"Leia atentamente as afirmativas a seguir, considerando os casos específicos de concordância nominal na norma culta da língua portuguesa. Analise cada construção com atenção e identifique aquelas em que a concordância nominal está correta. I.É proibido entrada de pessoas não autorizadas nas dependências do laboratório. II.Os documentos seguem anexos ao processo administrativo analisado pela comissão. III.As candidatas disseram obrigado pela oportunidade oferecida durante a seleção. IV.Eles ficaram alerta durante toda a operação realizada pela equipe de segurança. V.Os alunos procuraram resolver o maior número de exercícios possíveis antes da prova. Em quais afirmativas a concordância nominal está correta?","opcoes":["Apenas II, IV e V.","Apenas III, IV e V.","Apenas I, III e V.","Apenas I, II e IV."],"correta":3,"explicacao":"Gabarito: <strong>Apenas I, II e IV.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6317,"enunciado":"Leia atentamente as afirmativas abaixo: I.Seguem anexas ao processo as declarações emitidas pela comissão avaliadora do concurso. II.É proibida a entrada de pessoas sem identificação nas dependências do laboratório. III.Os técnicos permaneceram alertas diante das inconsistências verificadas no relatório final. IV.Havia menas dificuldades operacionais após a atualização dos sistemas administrativos da instituição. V.As candidatas disseram obrigada pela atenção concedida durante a reunião extraordinária. Identifique em quais das afirmativas lidas há erro de concordância nominal.","opcoes":["I, II e III.","II, III e IV.","I, IV e V.","III, IV e V."],"correta":3,"explicacao":"Gabarito: <strong>III, IV e V.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6322,"enunciado":"Considere as regras de concordância nominal na norma culta da língua portuguesa, especialmente no que se refere à relação entre substantivos e seus determinantes ou modificadores. Analise atentamente as alternativas a seguir, observando o emprego dessas regras em diferentes contextos sintáticos. Em seguida, identifique em qual alternativa há erro na concordância nominal.","opcoes":["As fotografias seguem anexas ao relatório final apresentado pela comissão avaliadora do projeto.","As crianças permaneceram meio nervosas durante a apresentação realizada no auditório central.","Os alunos e as alunas dedicados participaram ativamente das atividades propostas no curso.","É proibido a entrada de pessoas não autorizadas nas dependências internas do edifício."],"correta":3,"explicacao":"Gabarito: <strong>É proibido a entrada de pessoas não autorizadas nas dependências internas do edifício.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6362,"enunciado":"O trecho [...] abrigando variadas ações de compradores e vendedores obedece às regras de concordância nominal da norma culta. Se o vocábulo ações fosse substituído por projetos, assinale a alternativa que apresenta a reescrita CORRETA da frase.","opcoes":["abrigando variadas projetos de compradores e vendedores.","abrigando variados projetos de compradores e vendedores.","abrigando variado projetos de compradores e vendedores.","abrigando projetos variadas de compradores e vendedores.","abrigando variadamente projetos de compradores e vendedores."],"correta":1,"explicacao":"Gabarito: <strong>abrigando variados projetos de compradores e vendedores.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["concordancia"]},{"id":6375,"enunciado":"A concordância nominal, no português, depende da relação estabelecida entre o núcleo do sintagma e seus determinantes e modificadores, exigindo atenção à flexão de gênero e número. Considerando esse princípio, assinale a alternativa em que a concordância nominal está adequada à norma padrão.","opcoes":["Foram identificado complicações neurológicas graves.","Foi identificadas alterações no sistema nervoso.","Foram identificadas alterações neurológicas significativas.","Foi identificado alterações graves no organismo.","Foram identificada complicações associadas à doença."],"correta":2,"explicacao":"Gabarito: <strong>Foram identificadas alterações neurológicas significativas.</strong>.","banca":"Instituto Legatus","ano":2026,"temas_relacionados":["concordancia"]},{"id":6386,"enunciado":"Tratando-se de concordância nominal, assinale a alternativa incorreta.","opcoes":["Encontrei pai e filha empenhada numa discussão.","Os jogadores tinham sido convocados.","O governo avisa que não serão permitidas invasões de propriedades.","Foi feita a entrega dos convites."],"correta":0,"explicacao":"Gabarito: <strong>Encontrei pai e filha empenhada numa discussão.</strong>.","banca":"MSConcursos","ano":2026,"temas_relacionados":["concordancia"]},{"id":6395,"enunciado":"Assinale a alternativa em que a palavra destacada apresenta concordância correta com o ser a que se refere.","opcoes":["Todas as pessoas ficaram satisfeito com a festa-surpresa.","Eles costumam chegar aqui muito enjoado por causa das curvas da estrada.","Assim que elas vieram, fui logo saber se ficaram emocionadas com a recepção.","Muito assustado, os soldados que estavam na linha de frente acabaram recuando.","Elas são altamente capaz de realizar as tarefas mais difíceis da empresa."],"correta":2,"explicacao":"Gabarito: <strong>Assim que elas vieram, fui logo saber se ficaram emocionadas com a recepção.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6396,"enunciado":"Assinale a alternativa em que as palavras preenchem corretamente os espaços em branco abaixo, na mesma ordem: \"_______ ele chegou, já foi perguntando se havia feito um ________ negócio, e se era por isso que todos estavam passando __________.\"","opcoes":["Mau – mau – mal","Mal - mal - mal","Mal - mau – mal","Mal - mau – mau","Mau – mal – mau"],"correta":2,"explicacao":"Gabarito: <strong>Mal - mau – mal</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6401,"enunciado":"Analise as sentenças quanto à concordância nominal das palavras destacadas: I. A aula encerraria meio-dia e meio. II. As explicações foram o mais simples possível para que todos entendessem. III. É necessário paciência para construir o conhecimento. Está correta a concordância em:","opcoes":["II, apenas.","I e III, apenas.","I, II e III.","I, apenas.","II e III, apenas."],"correta":4,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":6413,"enunciado":"Outro ponto relevante é a forma de governança. As evidências sugerem uma administração coletiva e estruturada, responsável pela manutenção das cidades, sem sinais claros de poder concentrado. Assinale a alternativa correta quanto à concordância nominal no trecho apresentado.","opcoes":["O termo \"responsável\" é invariável por atuar como advérbio, não estabelecendo concordância com outros termos da frase.","A expressão \"poder concentrado\" apresenta adjetivo que concorda com \"sinais\", formando uma relação de concordância indireta no trecho.","Os adjetivos \"coletiva\" e \"estruturada\" concordam com \"administração\", assim como \"responsável\", que retoma esse mesmo núcleo.","O adjetivo \"governança\" concorda com o substantivo \"forma\", estabelecendo com esse núcleo uma relação de concordância nominal no período."],"correta":2,"explicacao":"Gabarito: <strong>Os adjetivos \"coletiva\" e \"estruturada\" concordam com \"administração\", assim como \"responsável\", que retoma esse mesmo núcleo.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6479,"enunciado":"Analise as concordâncias nominais feitas nas construções a seguir: I.Nem uma nem outra justificativa é válida porque você sempre mente. II.Elas próprias fizeram o roteiro da viagem e planejaram a travessia de barco da costa brasileira à costa africana. III.Dado a circunstância meteorológica, adiaram a saída do porto por dois dias. Está correta a concordância nominal em:","opcoes":["II e III, apenas.","I, II e III.","I e II, apenas.","I, apenas.","III, apenas."],"correta":2,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":6540,"enunciado":"A concordância nominal e a concordância verbal figuram como elementos fundamentais para a precisão expressiva em textos de caráter formal, pois exigem a articulação harmônica entre sujeitos, predicativos, adjuntos adnominais e concordância de número e pessoa nos verbos. Erros reiterados nessas áreas podem comprometer seriamente a legibilidade e a coerência do discurso escrito. Qual frase segue rigorosamente esses princípios, segundo a norma padrão?","opcoes":["“As diretoras competentes e o gerente operacional apresentaram relatórios plenamente estruturado, alinhando objetivos e métricas.”","“A pesquisadora minuciosa e os estagiários criterioso cumpriram prazos apertadas, finalizando estudos relevantes.”","“Os laudos científicos, detalhados e atuais, corroboram as conclusões, fornecendo bases sólidas para decisões.”","“Cada um dos gestores e a funcionária graduadas manteve-se cautelosos na revisão, evitando discrepâncias evidentes.”"],"correta":2,"explicacao":"Gabarito: <strong>“Os laudos científicos, detalhados e atuais, corroboram as conclusões, fornecendo bases sólidas para decisões.”</strong>.","banca":"JVL Concursos","ano":2025,"temas_relacionados":["concordancia"]},{"id":6557,"enunciado":"Assinale a alternativa em que a concordância nominal está INCORRETA.","opcoes":["As apostas são atividades arriscadas e viciantes.","O impacto das apostas é problemático e irreversível.","As plataformas de jogos são lucrativas e atraentes.","A legislação brasileira parece defasada e ineficaz.","Os jogos foram bem-sucedido e lucrativos."],"correta":4,"explicacao":"Gabarito: <strong>Os jogos foram bem-sucedido e lucrativos.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["concordancia"]},{"id":6631,"enunciado":"Ao redigir um ofício destinado a uma autoridade pública, o servidor deve observar que os pronomes de tratamento:","opcoes":["exigem concordância verbal na segunda pessoa do plural.","exigem concordância verbal na segunda pessoa do singular.","admitem tratamento simultâneo na segunda e terceira pessoas para maior formalidade","embora se refiram à pessoa com quem se fala, exigem concordância verbal, nominal e pronominal na terceira pessoa.","dispensam regras específicas de concordância em documentos oficiais."],"correta":3,"explicacao":"Gabarito: <strong>embora se refiram à pessoa com quem se fala, exigem concordância verbal, nominal e pronominal na terceira pessoa.</strong>.","banca":"Instituto IACP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6695,"enunciado":"Preencha os espaços em branco abaixo com \"eu\" ou \"mim\", adequadamente. A seguir, marque a alternativa que apresenta as formas corretas, na mesma ordem. – Traga o livro para ler uma história interessante para você. – Para , isso que você me disse não passa de um conto de fadas. – Fica muito dificil para coordenar os trabalhos da casa e da escola ao mesmo tempo.","opcoes":["mim - eu - eu","eu - eu - mim","eu - mim - eu","mim - eu - mim","mim - mim - mim"],"correta":2,"explicacao":"Gabarito: <strong>eu - mim - eu</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6752,"enunciado":"\"Somente entre 2023 e 2025, foram destinados R$ 6,5 bilhões para aquisição de livros e materiais didáticos, beneficiando milhões de estudantes e professores da rede pública brasileira.\" Analise as afirmativas a seguir: I.A forma verbal 'foram destinados' está corretamente flexionada no plural, pois concorda com o sujeito 'aquisição de livros e materiais didáticos'. PORQUE II.Em construções com o verbo na voz passiva, a concordância verbal deve ser feita com o sujeito paciente da oração, que, nesse caso, é composto por dois núcleos. Assinale a alternativa correta.","opcoes":["A afirmativa I é verdadeira, e a II é falsa.","As duas afirmativas são falsas.","As afirmativas I e II são verdadeiras, e a II justifica a I.","As afirmativas I e II são verdadeiras, mas a II não justifica a I."],"correta":0,"explicacao":"Gabarito: <strong>A afirmativa I é verdadeira, e a II é falsa.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6754,"enunciado":"\"Naquele período, apenas 45,4% das escolas brasileiras tinham acesso à conectividade considerada adequada.\" Com base na concordância verbal, analise as afirmativas: I.O verbo 'ter' está corretamente flexionado no plural, pois, em construções que expressam porcentagem, a concordância verbal pode ser realizada com o termo preposicionado que especifica a referência numérica. II.A forma verbal 'tinha' estaria igualmente correta, pois, em construções com porcentagem, admite-se também a concordância do verbo com a expressão numérica, '45%', que antecede o termo especificador. Assinale a alternativa correta.","opcoes":["A asserção I é verdadeira, e a II é falsa.","As asserções I e II são verdadeiras, mas a II não é uma justificativa correta da I.","As asserções I e II são verdadeiras, e a II é uma justificativa correta da I.","As asserções I e II são falsas."],"correta":0,"explicacao":"Gabarito: <strong>A asserção I é verdadeira, e a II é falsa.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6760,"enunciado":"No período “Fazemos coisas estranhas”, o sujeito da forma verbal “fazemos” é classificado como:","opcoes":["sujeito simples.","sujeito composto.","sujeito desinencial.","sujeito indeterminado."],"correta":2,"explicacao":"Gabarito: <strong>sujeito desinencial.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["concordancia"]},{"id":6761,"enunciado":"Com base nas normas de concordância verbal, assinalar a alternativa CORRETA.","opcoes":["Muitas pessoas haverão de existir na Terra.","Alguns alunos haviam participado da eleição.","Houveram muitas chuvas neste estado.","Podem haver muitas inscrições neste concurso."],"correta":1,"explicacao":"Gabarito: <strong>Alguns alunos haviam participado da eleição.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["concordancia"]},{"id":6771,"enunciado":"Considere o trecho: …e vem sendo estudada há alguns anos por especialistas… De acordo com as regras de concordância verbal da norma-padrão, se a forma verbal sublinhada fosse substituída pelo verbo fazer, a concordância CORRETA seria:","opcoes":["fazem alguns anos.","faz alguns anos.","farão alguns anos.","fizessem alguns anos."],"correta":1,"explicacao":"Gabarito: <strong>faz alguns anos.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["concordancia"]},{"id":6778,"enunciado":"Considerando as informações do Texto e as regras de concordância verbal da norma-padrão, assinale a alternativa correta:","opcoes":["Cerca de 90 adultos com sobrepeso ou obesidade participou do estudo.","Mais de um voluntário foram submetidos aos procedimentos da pesquisa.","A bactéria e o placebo foi utilizado durante o experimento.","Os participantes do grupo placebo recuperaram mais peso do que os participantes que receberam a bactéria."],"correta":3,"explicacao":"Gabarito: <strong>Os participantes do grupo placebo recuperaram mais peso do que os participantes que receberam a bactéria.</strong>.","banca":"ABCP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6784,"enunciado":"\"A hibridização, combinando motores elétricos com o uso de etanol, representa uma solução eficiente para acelerar o processo de descarbonização, oferecendo resultados imediatos na redução de emissões.\" Com base na concordância verbal, avalie se a asserção (A) é verdadeira e se a razão (R) é uma explicação correta da asserção. (A): No período acima, a concordância verbal está corretamente estabelecida, uma vez que o verbo 'representar' concorda com o sujeito. (R): O verbo 'representar' concorda com os núcleos do sujeito composto, 'hibridização' e 'motores elétricos', mantendo a correção gramatical. Assinale a alternativa que apresenta a relação correta entre a asserção (A) e a razão (R).","opcoes":["A asserção é falsa, e a razão é verdadeira.","A asserção é verdadeira, e a razão é falsa.","A asserção e a razão são verdadeiras, e a razão justifica corretamente a asserção.","A asserção e a razão são verdadeiras, mas a razão não justifica corretamente a asserção."],"correta":1,"explicacao":"Gabarito: <strong>A asserção é verdadeira, e a razão é falsa.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6788,"enunciado":"Analise as assertivas sobre concordância verbal. I. Na frase “Faltaram argumentos convincentes durante o debate”, o verbo concorda corretamente com o sujeito “argumentos convincentes”. II. Em “Havia muitos estudantes na biblioteca”, o verbo deveria estar no plural para concordar com “muitos estudantes”. III. Na frase “EUA anunciaram novas medidas econômicas”, o verbo está corretamente empregado no plural. Assinale a alternativa correta:","opcoes":["Apenas as assertivas I e II estão corretas.","Apenas as assertivas II e III estão corretas.","Apenas as assertivas I e III estão corretas.","Apenas a assertiva I está correta."],"correta":3,"explicacao":"Gabarito: <strong>Apenas a assertiva I está correta.</strong>.","banca":"Instituto Indec","ano":2026,"temas_relacionados":["concordancia"]},{"id":6818,"enunciado":"\"Nesse processo de conscientização, ele citou que, entre os desafios brasileiros (e também internacionais) está o contexto das mudanças climáticas como ameaça aos bens materiais e imateriais.\" Analise as asserções sobre o trecho acima. I. O verbo 'estar' encontra-se corretamente flexionado no singular, estabelecendo concordância com o sujeito posposto ao verbo, em construção caracterizada pela anteposição do adjunto adverbial, recurso que altera a ordem canônica dos termos da oração sem comprometer a relação de concordância verbal. PORQUE II. Quando o sujeito simples está posposto ao verbo e seu núcleo é um substantivo no singular, a concordância verbal realiza-se com esse núcleo, mantendo o verbo no singular, ainda que o sujeito venha acompanhado de adjuntos ou complementos nominais capazes de induzir o falante a uma flexão verbal inadequada no plural. Após análise, assinale a alternativa correta.","opcoes":["A primeira asserção é verdadeira, e a segunda é falsa.","As duas asserções são falsas.","As duas asserções são verdadeiras, mas a segunda não é uma justificativa correta da primeira.","As duas asserções são verdadeiras, e a segunda é uma justificativa correta da primeira."],"correta":3,"explicacao":"Gabarito: <strong>As duas asserções são verdadeiras, e a segunda é uma justificativa correta da primeira.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6821,"enunciado":"\"Ao longo de uma semana, foram realizados seminários, apresentações musicais de expressões afro-brasileiras, mesas temáticas, descerramento de placa simbólica e a Cerimônia de Toque para Iemanjá...\". Quanto à concordância verbal e nominal, analise as asserções a seguir: I. A expressão 'foram realizados' está corretamente flexionada no plural em razão de concordância com o sujeito composto posposto, \"seminários, apresentações musicais de expressões afro-brasileiras, mesas temáticas, descerramento de placa simbólica e a Cerimônia de Toque para Iemanjá\", sendo o particípio 'realizados' igualmente flexionado no masculino plural por concordância com o conjunto do sujeito composto. PORQUE II. Na voz passiva analítica, o verbo auxiliar concorda obrigatoriamente com o sujeito paciente em número e pessoa, ao passo que o particípio do verbo principal concorda com esse mesmo sujeito em gênero e número, sendo essa dupla concordância, verbal e nominal, o que distingue sintaticamente a voz passiva analítica de outras construções em que o particípio pode funcionar como adjunto adnominal ou predicativo, sem exigir a presença de verbo auxiliar. Assinale a alternativa correta.","opcoes":["As duas asserções são verdadeiras, e a segunda é uma justificativa correta da primeira.","As duas asserções são verdadeiras, mas a segunda não é uma justificativa correta da primeira.","A primeira asserção é falsa, e a segunda é verdadeira.","As duas asserções são falsas"],"correta":0,"explicacao":"Gabarito: <strong>As duas asserções são verdadeiras, e a segunda é uma justificativa correta da primeira.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6838,"enunciado":"O verbo “causar” (linha 25) possui sua concordância verbal vinculada a qual termo do texto?","opcoes":["“Armas biológicas” (linha 22).","“Bombas de barril” (linha 24).","“Sofrimento” (linha 26).","\"Armamentos” (linha 23)."],"correta":1,"explicacao":"Gabarito: <strong>“Bombas de barril” (linha 24).</strong>.","banca":"ABCP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6844,"enunciado":"A concordância do verbo \"estão\", no segundo parágrafo, é estabelecida com o termo:","opcoes":["aquelas.","associadas.","alimentares.","escolhas.","chamadas."],"correta":0,"explicacao":"Gabarito: <strong>aquelas.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["concordancia"]},{"id":6848,"enunciado":"Assinale a alternativa em que a concordância verbal está CORRETA:","opcoes":["Fazem dois anos que o projeto foi iniciado.","Houveram muitos problemas durante a reunião.","Existe várias soluções para o caso.","Devem haver alternativas mais eficientes.","Faz dois anos que o projeto foi iniciado."],"correta":4,"explicacao":"Gabarito: <strong>Faz dois anos que o projeto foi iniciado.</strong>.","banca":"FAU","ano":2026,"temas_relacionados":["concordancia"]},{"id":6874,"enunciado":"A concordância verbal é a norma gramatical que estabelece a harmonia entre o verbo e o seu respectivo sujeito. Sabendo disso, e atento à gramática da norma-padrão da língua portuguesa, indique a alternativa em que a concordância verbal se encontra correta.","opcoes":["A maioria dos 200 milhões de técnicos, que antes apenas assistiam aos jogos, agora julga cada lance com o rigor do VAR.","Cerca de 22 indivíduos, movidos pela paixão e pela busca da esfera de couro, persegue o objetivo da vitória no gramado.","Mais de um jornalista, no calor da discussão nos grupos de mensagens, criticaram duramente o cotovelo pixelado do atacante.","Não se sabe se foi os 100 milhões de técnicos ou os atuais 200 milhões de árbitros que transformou o futebol em tribunal."],"correta":0,"explicacao":"Gabarito: <strong>A maioria dos 200 milhões de técnicos, que antes apenas assistiam aos jogos, agora julga cada lance com o rigor do VAR.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["concordancia"]},{"id":6878,"enunciado":"Considere o trecho: “o Conselho Federal de Enfermagem (Cofen), o Ministério da Saúde e outras instituições lançaram plataformas digitais de combate à desinformação”. Se o sujeito fosse modificado para “o Conselho Federal de Enfermagem, juntamente com o Ministério da Saúde”, a concordância verbal correta, segundo a norma culta, seria:","opcoes":["“o Conselho Federal de Enfermagem, juntamente com o Ministério da Saúde, lançaram plataformas digitais” — a expressão “juntamente com” é equivalente à conjunção “e” e forma sujeito composto, que no contexto apresentado e pela regra geral, exige o plural.","“o Conselho Federal de Enfermagem, juntamente com o Ministério da Saúde, lançou plataformas digitais” — a expressão “juntamente com” é uma locução prepositiva que integra um adjunto adnominal ao sujeito singular, mantendo o verbo no singular em concordância com o núcleo do sujeito.","“o Conselho Federal de Enfermagem, juntamente com o Ministério da Saúde, lançaram plataformas digitais” — a norma culta admite tanto o singular quanto o plural nesse contexto, sendo o plural preferível por conferir maior naturalidade ao enunciado.","“o Conselho Federal de Enfermagem, juntamente com o Ministério da Saúde, lançou plataformas digitais” — o verbo no singular é obrigatório porque “juntamente com” é conjunção aditiva que une sujeitos de diferentes pessoas gramaticais, exigindo concordância com o primeiro núcleo."],"correta":1,"explicacao":"Gabarito: <strong>“o Conselho Federal de Enfermagem, juntamente com o Ministério da Saúde, lançou plataformas digitais” — a expressão “juntamente com” é uma locução prepositiva que integra um adjunto adnominal ao sujeito singular, mantendo o verbo no singular em concordância com o núcleo do sujeito.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["concordancia"]},{"id":6890,"enunciado":"As regras de concordância verbal admitem variações condicionadas por fatores sintáticos e semânticos, especialmente quando o núcleo do sujeito apresenta valor coletivo, partitivo ou expressões de quantidade. Em textos formais, o reconhecimento dessas estruturas é essencial para a adequação à norma-padrão. Com base nessas considerações, assinale a alternativa em que a concordância verbal está correta, segundo a normapadrão da Língua Portuguesa.","opcoes":["A maioria dos participantes concordou com as propostas dos candidatos que ali residia.","Fazem cinco anos que a instituição foi fundada, apesar das enchentes terem sido recentes.","O eclipse lunar acontece todo ano, e existe muitos fatores que explicam o fenômeno.","Mais de um pesquisador levantou a mesma hipótese a ser defendida pelos autores."],"correta":3,"explicacao":"Gabarito: <strong>Mais de um pesquisador levantou a mesma hipótese a ser defendida pelos autores.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["concordancia"]},{"id":6899,"enunciado":"As regras de concordância verbal admitem variações condicionadas por fatores sintáticos e semânticos, especialmente quando o núcleo do sujeito apresenta valor coletivo, partitivo ou expressões de quantidade. Em textos formais, o reconhecimento dessas estruturas é essencial para a adequação à norma-padrão. Com base nessas considerações, assinale a alternativa em que a concordância verbal está correta, segundo a norma padrão da Língua Portuguesa.","opcoes":["A maioria dos participantes concordou com as propostas dos candidatos que ali residia.","Fazem cinco anos que a instituição foi fundada, apesar das enchentes terem sido recentes.","O eclipse lunar acontece todo ano, e existe muitos fatores que explicam o fenômeno.","Mais de um pesquisador levantou a mesma hipótese a ser defendida pelos autores."],"correta":3,"explicacao":"Gabarito: <strong>Mais de um pesquisador levantou a mesma hipótese a ser defendida pelos autores.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["concordancia"]},{"id":6901,"enunciado":"Preencha os espaços em branco abaixo com o verbo entre parênteses, adequadamente. A seguir, marque a alternativa que apresenta as formas corretas, na mesma ordem. – Só vou ajudar você quando todo o material de estudo. (trazer) – Estarei aqui quando você o que lhe pedi. (fazer) – Quando você à minha casa, eu lhe contarei tudo. (vir)","opcoes":["trazer - fizer - vir","trazer - fazer - vir","trazer – fazer – vier","trouxer – fazer - vir","trouxer – fizer – vier"],"correta":4,"explicacao":"Gabarito: <strong>trouxer – fizer – vier</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":6904,"enunciado":"As normas de concordância verbal estão plenamente observadas na frase:","opcoes":["Faltava a todos os locais e cantos pesquisados a surpresa que o menino teria caso desse ali pelo que buscava.","Há coisas que a ninguém importariam não encontrar, dada a pouca importância que ganham em sua busca.","A quem poderia espantar buscas tão incompreensivas, senão aos meninos que cultivam os prazeres físicos da infância?","São nas insistências pessoais que se delineia a personalidade dos meninos obcecados e dos poetas renitentes.","Juntam-se aos prazeres do menino em sua busca obsessiva a satisfação de uma possível vingança final."],"correta":0,"explicacao":"Gabarito: <strong>Faltava a todos os locais e cantos pesquisados a surpresa que o menino teria caso desse ali pelo que buscava.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["concordancia"]},{"id":6915,"enunciado":"Assinale a alternativa que atende à norma-padrão de concordância verbal.","opcoes":["As manobras navais e as manobras artificiais para conter a fúria inflacionária do eleitorado faz desaparecer a energia política do mundo.","A prioridade absoluta nos países ocidentais e nas suas periferias é garantir que hajam bombas de combustível cheias a qualquer custo.","Existe situações difíceis das quais a humanidade têm a possibilidade de escapar para criar um futuro mais sustentável e limpo.","A infraestrutura de matrizes limpas com senso de urgência deveriam ser a prioridade da energia do mundo atual e não o eleitorado.","Os seres humanos dispõem agora da oportunidade histórica para decretar, de uma vez por todas, o fim da era dos combustíveis fósseis."],"correta":4,"explicacao":"Gabarito: <strong>Os seres humanos dispõem agora da oportunidade histórica para decretar, de uma vez por todas, o fim da era dos combustíveis fósseis.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["concordancia"]},{"id":7377,"enunciado":"\"Já quem ganhava menos de 60 libras não era taxado.\" A concordância verbal com o pronome 'quem', como no exemplo apresentado, pode variar de acordo com o contexto. O mesmo fenômeno ocorre com o pronome 'que'. Com base nisso, analise as construções a seguir. I.És tu quem me dás alegria de viver. II.Fomos nós quem fez este texto. III.Fui o primeiro que conseguiu sair. IV.Sou eu o primeiro que sei classificar o termo da oração. Assinale a alternativa que apresenta as frases com a concordância adequada.","opcoes":["II e III, apenas.","I, II, III e IV.","I e IV, apenas.","I e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":7391,"enunciado":"Assinale a alternativa em que os elementos preenchem corretamente os espaços em branco a seguir, na mesma ordem: - __________ você mora? - __________ você quer ir? - Estou exatamente __________ você pensa que estou.","opcoes":["Aonde - Onde - onde","Onde - Aonde - onde","Onde - Onde - aonde","Aonde - Onde - aonde","Aonde - Aonde - aonde"],"correta":1,"explicacao":"Gabarito: <strong>Onde - Aonde - onde</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":7495,"enunciado":"No trecho: “mais de 60% das pessoas relatam dormir menos de 7 horas por dia”, a concordância verbal está correta porque o verbo concorda com:","opcoes":["o termo “dia” posposto ao verbo.","o núcleo do sujeito expresso pela porcentagem.","o sujeito oculto da oração.","o predicativo do sujeito.","a expressão adverbial de tempo."],"correta":1,"explicacao":"Gabarito: <strong>o núcleo do sujeito expresso pela porcentagem.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["concordancia"]},{"id":7501,"enunciado":"Considerando as regras de concordância verbal e nominal da norma-padrão da língua portuguesa, analise as afirmativas a seguir a partir de trechos do texto. I. Em “Há sempre quem queira ordem, rotina, controle”, o verbo “haver” permanece no singular por apresentar sentido de existência. II. No trecho “A vida de Mel e Jack virou um acúmulo interminável de problemas”, o verbo poderia flexionar-se no plural (“viraram”) sem prejuízo da correção gramatical, devido ao sujeito composto. III. Em “Nessas horas, a gente tenta escapar”, a expressão “a gente” admite, na normapadrão, concordâcia verbal no singular. IV. No trecho “o que aparece ali diz mais sobre nós”, o verbo “dizer” concorda com o pronome demonstrativo “o”. V. Em “algumas com histórias mal resolvidas entre si”, o adjetivo “resolvidas” estabelece concordância nominal com “algumas”. Após análise, conclui-se que estão corretas:","opcoes":["II, IV e V.","I, II e V.","I, III, IV e V.","I, III e IV.","II, III, IV e V."],"correta":3,"explicacao":"Gabarito: <strong>I, III e IV.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["concordancia"]},{"id":7503,"enunciado":"Considerando as regras de concordância de acordo com a norma-padrão, analise as afirmativas a seguir: I.No trecho 'estamos lendo mais palavras do que nunca', o verbo 'estar' apresenta sujeito implícito, indicando que o enunciador se inclui entre os leitores, o que determina a flexão verbal na primeira pessoa do plural como única forma de concordância possível nesse contexto. II.Em 'a maioria vem em pequenas pílulas', o verbo 'vir' concorda adequadamente com o núcleo do sujeito 'maioria', devendo obrigatoriamente permanecer no singular. III.No trecho 'as pessoas a seu redor conversam umas com as outras', o verbo 'conversar' concorda com o núcleo do sujeito 'pessoas', no plural, seguindo a regra geral de concordância verbal, em que o verbo flexiona em número e pessoa de acordo com o sujeito. IV.Em 'não existe uma programação genética nos humanos para aprender a ler', o verbo 'existir' está no singular, pois pertence a uma oração sem sujeito, devendo permanecer na terceira pessoa do singular. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["II e IV, apenas.","I e III, apenas.","I, II e III, apenas.","I, II, III e IV."],"correta":2,"explicacao":"Gabarito: <strong>I, II e III, apenas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["concordancia"]},{"id":7506,"enunciado":"A respeito das relações de concordância estabelecidas no texto, assinale a alternativa correta.","opcoes":["O verbo “ilustrou” (linha 1) concorda com o nome “Peter Vandermeersh” (linha 1).","O verbo “incorporou” (linha 4) concorda com “investigação” (linha 4).","A locução verbal “foram geradas” (linha 5) concorda com “especialistas” (linha 5).","O verbo “correspondiam” (linha 7) concorda com “textos” (linha 7).","O verbo “evidenciou” (linha 23) concorda com “artigo” (linha 22)."],"correta":4,"explicacao":"Gabarito: <strong>O verbo “evidenciou” (linha 23) concorda com “artigo” (linha 22).</strong>.","banca":"Ibest","ano":2026,"temas_relacionados":["concordancia"]},{"id":7511,"enunciado":"Considerando as regras de concordância verbal e nominal da norma-padrão da língua portuguesa, analise as afirmativas a seguir a partir de trechos do texto. I. Em “Há sempre quem queira ordem, rotina, controle”, o verbo “haver” permanece no singular por apresentar sentido de existência. II. No trecho “A vida de Mel e Jack virou um acúmulo interminável de problemas”, o verbo poderia flexionar-se no plural (“viraram”) sem prejuízo da correção gramatical, devido ao sujeito composto. III. Em “Nessas horas, a gente tenta escapar”, a expressão “a gente” admite, na normapadrão, concordância verbal no singular. IV. No trecho “o que aparece ali diz mais sobre nós”, o verbo “dizer” concorda com o pronome demonstrativo “o”. V. Em “algumas com histórias mal resolvidas entre si”, o adjetivo “resolvidas” estabelece concordância nominal com “algumas”. Após análise, conclui-se que estão corretas:","opcoes":["II, IV e V.","I, II e V.","I, III, IV e V.","I, III e IV.","II, III, IV e V."],"correta":3,"explicacao":"Gabarito: <strong>I, III e IV.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["concordancia"]},{"id":7512,"enunciado":"\"Esses movimentos são movimentos sacádicos, também conhecidos como 'sacadas', e acontecem o tempo todo. Mesmo quando achamos que estamos olhando fixamente para algo, os olhos se movem discretamente de um ponto a outro.\" Considerando as regras de concordância verbal e nominal, julgue as afirmativas a seguir: I.O vocábulo 'conhecidos' concorda em gênero e número com 'movimentos sacádicos', exercendo função de predicativo e seguindo a regra de concordância nominal, pela qual o adjetivo deve concordar com o substantivo a que se refere. II.A forma verbal 'acontecem' está no plural em concordância com o sujeito 'esses movimentos', seguindo a regra geral de concordância verbal, pela qual o verbo concorda em número e pessoa com o sujeito da oração. III.O verbo 'achar' está na primeira pessoa do plural em concordância com o sujeito oculto de valor generalizante, referindo-se a qualquer pessoa que se encontre na situação descrita. IV.Em 'Existe uma razão anatômica para o olhar se mover o tempo todo', o verbo 'existir' pode ser substituído pela forma verbal 'Há', mantendo-se no singular, por se tratar de verbos impessoais que exigem o verbo nessa forma. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["I, II e III, apenas.","I e II, apenas.","III, apenas.","I, II, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III, apenas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["concordancia"]},{"id":7523,"enunciado":"As regras de concordância verbal determinam que o verbo deve concordar com o sujeito em número e pessoa, considerando diferentes estruturas sintáticas da oração. Em construções com sujeito simples, composto, coletivo, expressões partitivas e partículas apassivadoras, a concordância pode variar conforme a organização do enunciado e o valor semântico estabelecido na frase. Considerando as normas da concordância verbal na língua portuguesa, assinale a alternativa em que há erro de concordância verbal.","opcoes":["Nem o diretor nem os coordenadores compareceram à reunião extraordinária do conselho.","Vende-se equipamentos eletrônicos utilizados em atividades laboratoriais de alta precisão.","Grande parte dos pesquisadores concordou com as conclusões apresentadas no relatório técnico.","Fui eu quem apresentou os documentos exigidos durante a audiência administrativa."],"correta":1,"explicacao":"Gabarito: <strong>Vende-se equipamentos eletrônicos utilizados em atividades laboratoriais de alta precisão.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":7526,"enunciado":"Considere as regras de concordância nominal e verbal e assinale a alternativa INCORRETA:","opcoes":["Quando os portões foram abertos, percebemos que havia muitas pessoas naquele lugar","Já fazem dois anos que estou na lista de espera para aquela vaga de emprego.","Meus óculos caíram e quebraram a alça; precisei levá-los à ótica para consertá-los.","Houve três discursos espetaculares; a multidão estava estarrecida."],"correta":1,"explicacao":"Gabarito: <strong>Já fazem dois anos que estou na lista de espera para aquela vaga de emprego.</strong>.","banca":"Prefeitura de Chopinzinho - PR","ano":2026,"temas_relacionados":["concordancia"]},{"id":7539,"enunciado":"Considere a sequinte oração extraída do texto: o setor de eventos mantém o maior crescimento proporcional do estoque de empregos. Ao transpor essa oração para a voz passiva analítica, assinale a alternativa que apresenta a construção gramaticalmente CORRETA, preservando o sentido original e a concordância verbal.","opcoes":["Mantinha-se, pelo setor de eventos, o maior crescimento proporcional do estoque de empregos.","Pelo setor de eventos, o maior crescimento proporcional do estoque de empregos era mantido.","O maior crescimento proporcional do estoque de empregos mantém-se pelo setor de eventos.","O maior crescimento proporcional do estoque de empregos é mantido pelo setor de eventos.","O setor de eventos é mantido pelo maior crescimento proporcional do estoque de empregos."],"correta":3,"explicacao":"Gabarito: <strong>O maior crescimento proporcional do estoque de empregos é mantido pelo setor de eventos.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["concordancia"]},{"id":7550,"enunciado":"\"Essa estratégia foi observada em gralhas-pretas e corvos-marinhos selvagens. Estudos de laboratório com ratos na Noruega também mostraram que os ratos podem adquirir preferências alimentares ao cheirar o hálito de indivíduos mais atentos.\" Considerando as regras de concordância verbal e nominal, assinale a alternativa incorreta.","opcoes":["O verbo 'mostrar' está no plural em concordância com o núcleo do sujeito 'estudos'. Observa-se concordância adequada também na frase 'Passava naquele momento, por sua mente, a lembrança e a saudade dos tempos de infância'.","Caso o sujeito 'estudos...' fosse substituído por 'o conjunto dos estudos...', o verbo 'mostrar' deveria obrigatoriamente flexionar-se no singular, uma vez que substantivos coletivos exigem sempre concordância no singular.","O adjetivo 'atentos' concorda em gênero e número com 'indivíduos', exercendo função de adjunto adnominal, caracterizando e restringindo o conjunto de indivíduos referidos.","A expressão 'foi observada' está no singular em concordância com o sujeito 'essa estratégia', seguindo a regra geral de concordância verbal e nominal. Observa-se concordância adequada também em 'Nós não estamos sós'."],"correta":1,"explicacao":"Gabarito: <strong>Caso o sujeito 'estudos...' fosse substituído por 'o conjunto dos estudos...', o verbo 'mostrar' deveria obrigatoriamente flexionar-se no singular, uma vez que substantivos coletivos exigem sempre concordância no singular.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["concordancia"]},{"id":7553,"enunciado":"Analise a concordância dos verbos destacados: I.O enfraquecimento silencioso da musculatura é um dos principais fatores que comprometem a qualidade de vida na velhice. II.O ideal é que todas as pessoas chegassem à terceira idade acostumadas a se exercitar. III.A correria do trabalho, as responsabilidades da vida adulta e a falta de orientação faz com que o movimento fique de lado. Está correta a concordância verbal em:","opcoes":["I, apenas.","III, apenas.","I e II, apenas.","II e III, apenas.","I, II e III"],"correta":2,"explicacao":"Gabarito: <strong>I e II, apenas.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":7562,"enunciado":"Assinale a alternativa em que a concordância verbal está correta.","opcoes":["Haviam inúmeros documentos pendentes de análise.","Faziam dois meses que a comissão aguardava a resposta.","Existia várias irregularidades no processo.","Faz dois meses que a comissão aguardava a resposta."],"correta":3,"explicacao":"Gabarito: <strong>Faz dois meses que a comissão aguardava a resposta.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["concordancia"]},{"id":7573,"enunciado":"Acerca dos sentidos e de aspectos linguísticos do texto CG6A1, julgue o item que se segue. No trecho \"Isso implica compreender que a adoção de IA não se limita à implementação de ferramentas, mas exige a formação de servidores capazes\" (terceiro parágrafo), a forma verbal \"exige\" estabelece concordância com o termo \"adoção\".\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":7578,"enunciado":"Analise as sentenças a seguir quanto à concordância dos verbos destacados: I.Tanto o malabarismo quanto a palhaçaria são práticas da arte circense. II.Faz parte da cultura brasileira não só o cinema como o circo. III.O circo, com seus artistas, lutou para que a arte fosse reconhecida como manifestação da cultura brasileira. IV.Nem o circo nem o grafite deveriam ser excluídos do reconhecimento como arte popular no Brasil. Está correta a concordância dos verbos destacados em:","opcoes":["I, II e III, apenas.","IV, apenas.","I e II, apenas.","III e IV, apenas.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":7580,"enunciado":"A norma-padrão de concordância verbal foi respeitada em:","opcoes":["O apoio e a presença da família podem atenuar o sofrimento dos doentes.","Antigamente não haviam tantos medicamentos e exames médicos como hoje.","Existe profissionais da saúde muito competentes e dedicados ao trabalho.","A existência de diferentes especialidades médicas são algo importante.","Atualmente se contam com um grande volume de conhecimentos médicos."],"correta":0,"explicacao":"Gabarito: <strong>O apoio e a presença da família podem atenuar o sofrimento dos doentes.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["concordancia"]},{"id":7581,"enunciado":"Analise as sentenças a seguir quanto à concordância dos verbos destacados: I.Tanto o malabarismo quanto a palhaçaria são práticas da arte circense. II.Faz parte da cultura brasileira não só o cinema como o circo. III.O circo, com seus artistas, lutou para que a arte fosse reconhecida como manifestação da cultura brasileira. IV.Nem o circo nem o grafite deveriam ser excluídos do reconhecimento como arte popular no Brasil. Está correta a concordância dos verbos destacados em:","opcoes":["IV, apenas.","I e II, apenas","III e IV, apenas","I, II e III, apenas.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":7585,"enunciado":"Analise as sentenças a seguir quanto à concordância dos verbos destacados: I. Tanto o malabarismo quanto a palhaçaria são práticas da arte circense. II. Faz parte da cultura brasileira não só o cinema como o circo. III. O circo, com seus artistas, lutou para que a arte fosse reconhecida como manifestação da cultura brasileira. IV. Nem o circo nem o grafite deveriam ser excluídos do reconhecimento como arte popular no Brasil. Está correta a concordância dos verbos destacados:","opcoes":["III e IV, apenas.","I, II, III e IV.","I e II, apenas.","I, II e III, apenas.","IV, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":7595,"enunciado":"Analise as sentenças a seguir quanto à concordância dos verbos destacados: I.Tanto o malabarismo quanto a palhaçaria são práticas da arte circense. II.Faz parte da cultura brasileira não só o cinema como o circo. III.O circo, com seus artistas, lutou para que a arte fosse reconhecida como manifestação da cultura brasileira. IV.Nem o circo nem o grafite deveriam ser excluídos do reconhecimento como arte popular no Brasil. Está correta a concordância dos verbos destacados em:","opcoes":["V, apenas.","I, II e III, apenas.","I e II, apenas.","III e IV, apenas.","I, II, III e IV."],"correta":4,"explicacao":"Gabarito: <strong>I, II, III e IV.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":7616,"enunciado":"Considerando o trecho \"A maioria das agressões parte de outros estudantes, mas educadores também aparecem como agressores em parte dos relatos.\", analise o fenômeno de concordância verbal presente na expressão \"A maioria das agressões parte\", à luz da norma-padrão da língua portuguesa e de suas possibilidades de variação admitidas em contextos formais. Assinale a alternativa que apresenta a análise correta.","opcoes":["A forma verbal no singular estabelece concordância com o núcleo do sujeito \"maioria\", sendo igualmente admissível a flexão no plural por atração semântica, sem alteração de valor sintático do enunciado original.","O emprego do verbo no singular configura desvio da norma culta, pois o termo \"agressões\" determina obrigatoriamente a concordância verbal no plural, independentemente da presença de expressão partitiva no sujeito.","A concordância no singular decorre da indeterminação do sujeito expressa por \"maioria\", o que impede a flexão verbal no plural, mesmo em contextos que privilegiam a concordância com o termo semântico dominante.","A flexão verbal no singular resulta de concordância atrativa com o termo plural mais próximo, sendo a forma no plural preferível em registros formais por concordar diretamente com \"agressões\" no interior do sujeito composto."],"correta":0,"explicacao":"Gabarito: <strong>A forma verbal no singular estabelece concordância com o núcleo do sujeito \"maioria\", sendo igualmente admissível a flexão no plural por atração semântica, sem alteração de valor sintático do enunciado original.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":7625,"enunciado":"Assinale a alternativa cuja forma verbal destacada está sendo empregada corretamente quanto às normas oficiais de concordância.","opcoes":["Coube todas as frutas na sacola.","Dois terços do país passam fome lá.","A relação dos aprovados chegaram hoje.","Haviam muitas pendências no escritório.","Deu dez horas no relógio da estação."],"correta":1,"explicacao":"Gabarito: <strong>Dois terços do país passam fome lá.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["concordancia"]},{"id":7631,"enunciado":"As normas de concordância verbal estão plenamente observadas na frase:","opcoes":["A quem poderia espantar buscas tão incompreensíveis, senão aos meninos que cultivam os prazeres físicos da infância?","São nas insistências pessoais que se delineia a personalidade dos meninos obcecados e dos poetas renitentes.","Juntam-se aos prazeres do menino em sua busca obsessiva a satisfação de uma possível vingança final.","Faltava a todos os locais e cantos pesquisados a surpresa que o menino teria caso desse ali pelo que buscava.","Há coisas que a ninguém importariam não encontrar, dada a pouca importância que ganham em sua busca."],"correta":3,"explicacao":"Gabarito: <strong>Faltava a todos os locais e cantos pesquisados a surpresa que o menino teria caso desse ali pelo que buscava.</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["concordancia"]},{"id":7633,"enunciado":"Abaixo estão alguns trechos de Machado de Assis adaptados. Em relação à concordância verbal, assinale a alternativa em que o verbo está empregado de acordo com a norma-padrão da língua portuguesa.","opcoes":["“Haviam muitas recordações que me perseguiam naquela casa.” (Dom Casmurro)","“Existe nos homens certas vaidades difíceis de esconder.” (Memórias Póstumas de Brás Cubas)","“Faltava-lhe a coragem e a esperança necessárias para continuar.” (Quincas Borba)","“Devem haver razões ocultas para tamanho silêncio.” (Helena)","“Precisam-se de homens honestos para o cargo.” (Esaú e Jacó)"],"correta":2,"explicacao":"Gabarito: <strong>“Faltava-lhe a coragem e a esperança necessárias para continuar.” (Quincas Borba)</strong>.","banca":"IDHTEC","ano":2026,"temas_relacionados":["concordancia"]},{"id":7644,"enunciado":"Sobre a concordância verbal, assinalar a alternativa CORRETA.","opcoes":["Menos de dois alunos ficou reprovado na disciplina.","Devem existir várias pessoas boas no mundo.","A maioria do eleitorado votarão confusos.","EUA atacam a Venezuela no ano de 2026."],"correta":1,"explicacao":"Gabarito: <strong>Devem existir várias pessoas boas no mundo.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["concordancia"]},{"id":7646,"enunciado":"Assinale a alternativa em que há ERRO de concordância verbal:","opcoes":["Fazem muitos anos que a escola pública enfrenta dificuldades estruturais.","Havia muitos alunos aguardando na fila de matrícula.","Devem existir diversas estratégias para a melhoria do ensino.","Os professores parecem comprometidos com a aprendizagem dos estudantes."],"correta":0,"explicacao":"Gabarito: <strong>Fazem muitos anos que a escola pública enfrenta dificuldades estruturais.</strong>.","banca":"Estágios CIN","ano":2026,"temas_relacionados":["concordancia"]},{"id":7651,"enunciado":"A partir dos dados apresentados no terceiro parágrafo, analise as sentenças a seguir a respeito da concordância verbal dos verbos \"possuir\" e \"estar\": I.Em construções com expressões numéricas de porcentagem, o verbo concorda com o termo preposicionado que especifica esse número. Desse modo, o verbo \"estar\" concorda com \"da população\". II.Em construções com expressões numéricas de porcentagem, se o termo preposicionado não estiver explícito, a concordância se faz com o número. Assim, o verbo \"possuir\" concorda com 44%. III.Se o verbo anteceder a expressão de porcentagem, a concordância se fará com o número. É o que acontece nesta construção: Estão na mesma faixa de renda 38% da população não conectada à rede de esgoto. É correto o que se afirma em:","opcoes":["I e III, apenas.","I, II e III.","I, apenas.","II e III, apenas.","II, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FURB","ano":2026,"temas_relacionados":["concordancia"]},{"id":7652,"enunciado":"\"Dezenas de espécies catalogadas pelo termo genérico 'fungos zumbi' já foram descritas pela Ciência.\" O trecho acima apresenta concordância verbal e nominal adequadas. A partir desse trecho, analise as frases a seguir e identifique aquela que apresenta concordância INCORRETA.","opcoes":["É necessária a observação de que dezenas de espécies catalogadas pelo termo genérico 'fungos zumbi' já foram descritas pela Ciência.","Mais de uma espécie catalogada pelo termo genérico 'fungos zumbi' já foi descrita pela Ciência.","O nível de espécies catalogadas pelo termo genérico 'fungos zumbi' já foram descritas pela Ciência.","Número cada vez maior de espécies catalogadas pelo termo genérico 'fungos zumbi' estão sendo descritas pela Ciência."],"correta":2,"explicacao":"Gabarito: <strong>O nível de espécies catalogadas pelo termo genérico 'fungos zumbi' já foram descritas pela Ciência.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["concordancia"]},{"id":7655,"enunciado":"\"Entre as novidades, está a criação da carreira de analista técnico do Poder Executivo Federal (ATE), formada a partir da transformação de 6,9 mil cargos vagos de especialidades administrativas hoje distribuídas por diferentes órgãos.\" Considerando as regras de concordância verbal e nominal, analise as afirmativas a seguir: I.A forma verbal 'está' apresenta-se no singular, pois não apresenta sujeito explícito na oração, ainda que o predicativo do sujeito venha detalhado de forma extensa na sequência da oração. II.A palavra 'distribuídas' está corretamente no plural, pois concorda com 'especialidades', indicando que as especialidades administrativas se encontram repartidas entre diferentes órgãos. III.Caso a construção fosse '6,9 mil cargos vagos distribuídos', também seria admitida a forma 'distribuído', a depender da ênfase estilística do enunciador. Assinale a alternativa que apresenta a(s) proposição(ões) correta(s).","opcoes":["II, apenas.","I e III, apenas","II e III, apenas.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["concordancia"]},{"id":7923,"enunciado":"Leia o excerto a seguir. \"O café instantâneo, um dos mais consumidos ao redor mundo, está associado ao risco de câncer por conter duas vezes mais acrilamida - uma substância com potencial cancerígeno produzida quando alimentos passam por altas temperaturas durante o cozimento - do que as outras formas em que a bebida é produzida. A acrilamida é categorizada pela Iarc (Agência Internacional de Pesquisa em Câncer - em tradução) como \"provável cancerígeno humano\", algo que indica evidências fortes de que a substância pode causar câncer em seres humanos, mas não há provas conclusivas de seus efeitos. As informações são do ‘The Telegraph’.\" Disponível em: https://revistaplaneta.com.br/cafe-instantaneo-pode-aumentar-risco-de-cancer-entenda/. Acesso em: 19 nov. 2024. Analise as proposições a seguir, a respeito da sintaxe do excerto acima. I. A expressão \"um dos mais consumidos ao redor do mundo\" exerce a função de aposto explicativo. II. A preposição \"por\", presente no primeiro parágrafo, introduz uma expressão cuja ideia central é a de consequência. III. A estrutura \"pela Iarc\", citada no início do segundo parágrafo, é classificada sintaticamente como agente da passiva. IV. O verbo \"há\", empregado no segundo parágrafo, pode ser substituído pelo verbo \"existir\", mantendo-se a concordância verbal. Estão INCORRETAS as seguintes proposições:","opcoes":["II e III, apenas.","II e IV, apenas.","III e IV, apenas.","I e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>II e IV, apenas.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["concordancia"]},{"id":8018,"enunciado":"No enunciado “Nós vamos encontrá-lo, para que ele responda pelos crimes que ele está sendo acusado” (policial, em entrevista ao JPB 1 . Edição – 05/07/2015), registra-se um desvio da norma gramatical em relação:","opcoes":["à regência verbal.","à regência nominal.","à concordância nominal.","à concordância verbal.","ao uso do preposição para."],"correta":1,"explicacao":"Gabarito: <strong>à regência nominal.</strong>.","banca":"CPCON","ano":2017,"temas_relacionados":["concordancia"]},{"id":8216,"enunciado":"A imprensa internacional foi convidada para assistir os de- bates em Copenhague. De acordo com a norma escrita padrão da língua, na frase acima há um DESVIO de","opcoes":["regência nominal.","regência verbal.","concordância nominal.","concordância verbal.","pontuação. Texto II Fim do Mundo Estaria o mundo de hoje, e o Brasil junto com ele, se comprometendo com o que pode vir a ser a mais cara, obsessiva e mal informada ilusão científica da história? A humanidade já esteve convencida de que a 5 Terra era plana, e que era possível prever matematica- mente a extinção da vida humana por falta física de comida, já que a população cresceria sempre de forma geométrica e a produção de alimentos jamais poderia aumentar no mesmo ritmo; mais recentemente, gran- 10 des empresas, governos e ases da ciência digital acreditaram que o “bug do milênio” iria paralisar o mundo na passagem de 1999 para 2000. Não se pode dizer que a crescente convicção de que o planeta sofre hoje uma “ameaça sem precedentes” em toda a sua 15 existência, como resultado direto da “mudança do clima”, e particularmente do “aquecimento global”, seja exatamente a mesma coisa. A conferência de Copenhague tende a refletir, basicamente, um conjunto de neuroses, fantasias e 20 necessidades políticas que se ligam muito mais aos países ricos do que à realidade brasileira; a agenda central é deles, com seus números, seus cientistas e até sua linguagem. O Brasil, em vez de reagir ao debate dos outros, faria melhor pensando primeiro em seus 25 interesses. Para isso, precisaria saber o que quer. Parece bem claro que o País, antes de ter um proble- ma ecológico, tem um problema sanitário; nossa verdadeira tragédia ambiental é o fato de que 50% da população não dispõe de rede de esgotos, ou de que 30 dois terços dos esgotos são lançados nos rios sem tratamento nenhum. Na Amazônia, onde há o maior volume de água doce do mundo, a maioria da popula- ção não tem água decente para beber. Nas áreas pobres das cidades, o lixo não é coletado - acaba em 35 rios, represas ou na rua. A questão ecológica real, no Brasil, chama-se pobreza. GUZZO, J. R. Revista Veja. São Paulo: Abril, edição 2138, ano 42, no 45, 11 nov. 2009, p. 218. (Fragmento) 3"],"correta":1,"explicacao":"Gabarito: <strong>regência verbal.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["concordancia"]},{"id":8289,"enunciado":"A imprensa internacional foi convidada para assistir os de- bates em Copenhague. De acordo com a norma escrita padrão da língua, na frase acima há um DESVIO de","opcoes":["regência nominal.","regência verbal.","concordância nominal.","concordância verbal.","pontuação. Texto II Fim do Mundo Estaria o mundo de hoje, e o Brasil junto com ele, se comprometendo com o que pode vir a ser a mais cara, obsessiva e mal informada ilusão científica da história? A humanidade já esteve convencida de que a 5 Terra era plana, e que era possível prever matematica- mente a extinção da vida humana por falta física de comida, já que a população cresceria sempre de forma geométrica e a produção de alimentos jamais poderia aumentar no mesmo ritmo; mais recentemente, gran- 10 des empresas, governos e ases da ciência digital acreditaram que o “bug do milênio” iria paralisar o mundo na passagem de 1999 para 2000. Não se pode dizer que a crescente convicção de que o planeta sofre hoje uma “ameaça sem precedentes” em toda a sua 15 existência, como resultado direto da “mudança do clima”, e particularmente do “aquecimento global”, seja exatamente a mesma coisa. A conferência de Copenhague tende a refletir, basicamente, um conjunto de neuroses, fantasias e 20 necessidades políticas que se ligam muito mais aos países ricos do que à realidade brasileira; a agenda central é deles, com seus números, seus cientistas e até sua linguagem. O Brasil, em vez de reagir ao debate dos outros, faria melhor pensando primeiro em seus 25 interesses. Para isso, precisaria saber o que quer. Parece bem claro que o País, antes de ter um proble- ma ecológico, tem um problema sanitário; nossa verdadeira tragédia ambiental é o fato de que 50% da população não dispõe de rede de esgotos, ou de que 30 dois terços dos esgotos são lançados nos rios sem tratamento nenhum. Na Amazônia, onde há o maior volume de água doce do mundo, a maioria da popula- ção não tem água decente para beber. Nas áreas pobres das cidades, o lixo não é coletado - acaba em 35 rios, represas ou na rua. A questão ecológica real, no Brasil, chama-se pobreza. GUZZO, J. R. Revista Veja. São Paulo: Abril, edição 2138, ano 42, no 45, 11 nov. 2009, p. 218. (Fragmento) 4"],"correta":1,"explicacao":"Gabarito: <strong>regência verbal.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["concordancia"]},{"id":8556,"enunciado":"De acordo com as regras de concordância nominal da norma-padrão da língua portuguesa, a palavra destacada está empregada corretamente em:","opcoes":["A mudança das leis sobre o uso de agrotóxicos e a repressão dos órgãos de vigilância sanitária devem ser implementadas com urgência para evitar mais mortes.","As leis instituídas para proteger os cidadãos e os ensi- namentos dos estudiosos sobre o uso de agrotóxicos devem ser divulgadas para que tenham alcance geral.","O desenvolvimento de novas estratégias de plantio e a substituição da agricultura convencional pela or- gânica são consideradas uma exigência dos tempos atuais para muitos produtores rurais.","Os estudos realizados por especialistas de saúde em laboratórios e a busca por exterminar doenças conta- giosas são indicativas do progresso da medicina nos últimos tempos.","Os procedimentos orientados pelos especialistas e a concessão de verbas públicas pelos órgãos governa- mentais têm sido entendidas como imprescindíveis para o desenvolvimento da agricultura familiar."],"correta":0,"explicacao":"Gabarito: <strong>A mudança das leis sobre o uso de agrotóxicos e a repressão dos órgãos de vigilância sanitária devem ser implementadas com urgência para evitar mais mortes.</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["concordancia"]},{"id":21559,"enunciado":"No trecho \"Talvez aquilo tivesse sido feito por gente\" (L.5-6), o verbo concorda com \"gente\", sujeito da oração na voz passiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":85343,"enunciado":"A frase em que a concordância verbal e nominal está inteiramente respeitada é:","opcoes":["Ainda não foi suficiente os investimentos na tentativa de redução dos índices de pobreza verificados em todo o mundo.","Em relação ao poder aquisitivo, ainda se observa dados assustadores quanto à miséria em que vivem populações inteiras.","São claras algumas implicações políticas na área do desenvolvimento humano, pois é imprescindível a ação do poder público na erradicação da miséria.","Deve ser levado em conta a sustentabilidade do crescimento econômico, para que se garanta melhorias efetivas das condições de vida da população.","Alguns especialistas tende a atribuir à crise financeira a principal razão do retrocesso nos resultados satisfatórios que já tinha sido alcançado."],"correta":2,"explicacao":"Gabarito: <strong>São claras algumas implicações políticas na área do desenvolvimento humano, pois é imprescindível a ação do poder público na erradicação da miséria.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["concordancia"]},{"id":133035,"enunciado":"A respeito da reescritura do período “A despeito da sucessão de crises financeiras e cambiais que se abateram nos últimos 30 anos sobre os ex-periféricos (agora emergentes), a turma do Fundo Monetário continua a acreditar na fábula dos mercados eficientes”, entre as linhas 11 e 14 do texto, julgue os itens que se seguem.\n\nIdentifica-se erro de concordância verbal e de regência na seguinte reescritura: Em que pese as sucessivas crises financeiras e cambiais que arremeteram, nos últimos 30 anos, os ex-periféricos (agora emergentes), os integrantes do grupo do FMI seguem persuadidos no conto dos mercados eficientes.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":318336,"enunciado":"Em relação às informações e estruturas linguísticas do texto acima, julgue os itens que se seguem.\n\nPrejudica-se a correção gramatical do texto ao se substituir a expressão “Dez anos atrás” (l.3) por Há dez anos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":780587,"enunciado":"Na língua escrita padrão, leva-se em conta a relação de dependência estabelecida entre um termo e outro mediante um contexto, são as concordâncias e regências. A concordância verbal trata das alterações do verbo para se acomodar ao seu sujeito. Assinale a alternativa que apresenta a norma INADEQUADA para explicar a concordância verbal utilizada no trecho dado.","opcoes":["o norte-americano especialista em segurança da informação Dave Kearns costuma avisar → O verbo concorda com o sujeito em pessoa e número.","existe uma série de aplicativos, navegadores, redes sociais → Usa-se o verbo existir somente na terceira pessoa do singular, pois é impessoal.","das pessoas, empresas ou instituições que foram autorizadas → Quando o sujeito for pronome relativo, o verbo concorda com o antecedente desse pronome.","Tudo está disponível para alguém. E pode ser usado contra você. → Nos dois casos, o verbo concorda com o sujeito em pessoa e número."],"correta":1,"explicacao":"Gabarito: <strong>existe uma série de aplicativos, navegadores, redes sociais → Usa-se o verbo existir somente na terceira pessoa do singular, pois é impessoal.</strong>.","banca":"UFMT","ano":2017,"temas_relacionados":["concordancia"]},{"id":825811,"enunciado":"Julgue o item a respeito dos sentidos do texto e de seus aspectos linguísticos.\n\nEstaria mantida a correção gramatical do texto caso a forma verbal “tendem” (linha 3) estivesse flexionada na terceira pessoa do singular, dada a previsão, na gramática normativa, da concordância com o núcleo mais próximo do sujeito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1055642,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o iten.\n\n\nNa linha 16, estaria mantida a correção gramatical do texto caso a forma verbal “ultrapassaram” estivesse flexionada na terceira pessoa do singular, dada a possibilidade prevista na gramática de concordância com o vocábulo “que”, sujeito da oração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1101167,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item.\nNa linha 20, estaria mantida a correção gramatical do texto caso a forma verbal “haviam implantado” estivesse flexionada na terceira pessoa do singular, dada a possibilidade de concordância com a expressão percentual “50%”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1844365,"enunciado":"Com relação aos aspectos gramaticais e aos sentidos do texto, julgue o item.\n\n\n\n\nO uso do plural na locução “eram obtidos” (linha 29) é necessário para se estabelecer a correta concordância verbal com “o querosene, a gasolina e o gás de cozinha” (linha 30).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1865419,"enunciado":"O termo “descoberto” (linha 37) está flexionado no masculino e no singular porque estabelece uma relação de concordância nominal com a expressão “o alienista” (linha 34).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1913146,"enunciado":"Com relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nDe acordo com o texto, há uma concordância geral de que o bem-estar animal interfere no produto final.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1955637,"enunciado":"Julgue o item, relativos a aspectos linguísticos do texto. \n\n\n\n\nA flexão da forma verbal “tende” (linha 14) na terceira pessoa do singular justifica-se pela concordância do verbo com o termo “maioria” (linha 13), que é o núcleo do sujeito da oração.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":1978427,"enunciado":"Em relação aos aspectos gramaticais e aos sentidos do texto apresentado, julgue o item.\n\nNo último período do texto, o emprego do singular em “esteja” deve-se ao fato de que essa forma verbal estabelece concordância com o termo “metade”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2134714,"enunciado":"Quanto à ortografia oficial, à correção gramatical e à coerência das substituições propostas para os vocábulos e os trechos destacados do texto, julgue o item.\n\n\n\n\n“A Finlândia, aliás, lidera o ranking há cinco anos. Só que 18,8% da sua população tem algum problema psicológico, especialmente com o desenvolvimento de depressão – o percentual mais alto da União Europeia” (linhas de 17 a 20) por Há cinco anos a Finlândia lidera o ranking, apesar de 18,8% da sua população ter algum problema psicológico, especialmente depressão. Este percentual é o mais alto da União Europeia","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["concordancia","ortografia"]},{"id":2183466,"enunciado":"Considerando a estrutura e os aspectos linguísticos do texto, julgue o item.\n\n\n\n\nNa oração “O porteiro do edifício cochilava” (linhas 1 e 2), há um predicado nominal e um sujeito composto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2183478,"enunciado":"Acerca da estrutura e dos sentidos do texto, julgue o item.\n\n\n\n\nA forma verbal “chamam” (linha 9) estabelece concordância com o termo antecedente “me” (linha 8).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2320406,"enunciado":"Com base na leitura do texto e em seus aspectos linguísticos, de forma e de conteúdo, julgue o item a seguir.\n\nO termo “profissionais” (linha 5) funciona sintaticamente como núcleo do sujeito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2345633,"enunciado":"Com base na leitura do texto, julgue o item.\n\n\n\n\n\n\n\nNo trecho “Nesta ação, a atuação da equipe de Fiscalização da autarquia visa a conscientização sobre a importância do cumprimento das normas” (linhas de 6 a 8), há um erro de concordância verbal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2356222,"enunciado":"De acordo com a pontuação e a sintaxe de concordância nominal e verbal no texto, julgue o item.\n\n\n\n\nNa linha 2, as vírgulas empregadas após “humano” e “respiratório” separam termos em enumeração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2356224,"enunciado":"De acordo com a pontuação e a sintaxe de concordância nominal e verbal no texto, julgue o item.\n\n\n\n\nA flexão do vocábulo “relacionada” (linha 40) justifica‑se por sua concordância com o termo “doença” (linha 38).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2356225,"enunciado":"De acordo com a pontuação e a sintaxe de concordância nominal e verbal no texto, julgue o item.\n\n\n\n\nO sujeito da oração “Entre elas, destaca‑se a endocardite infecciosa” (linhas 23 e 24) é indeterminado, por isso o verbo está flexionado na terceira pessoa do singular e acompanhado da partícula “se”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2360380,"enunciado":"Acerca da tipologia, dos sentidos do texto e dos aspectos linguísticos, julgue o item.\n\n\n\n\nA locução verbal “sendo necessária” (linha 13), mesmo na ordem inversa do discurso, concorda com o sujeito composto apresentado na sequência – “a formação presencial e prática”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2385472,"enunciado":"Acerca de aspectos gramaticais do texto, julgue o item.\n\n\n\n\nNo segmento “Além disso, notou‑se também a redução de isolamento social até mesmo naquelas pessoas” (linhas 24 e 25), a flexão verbal na terceira pessoa do singular justifica‑se pela concordância do verbo com o termo “redução” (linha 24), que é o núcleo do sujeito da oração.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2467744,"enunciado":"Em relação à tira acima, julgue o item.\n\n\n\n\nNo primeiro quadrinho, na fala da menina, o núcleo do sujeito é “muito”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2469097,"enunciado":"Com relação a aspectos gerais do texto, julgue o item.\n\n\n\n\nO núcleo do sujeito da primeira oração do período “Mas, claramente, existe também um aspecto psicológico da coceira que ainda não entendemos totalmente” (linhas de 28 a 30) é “aspecto”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":2500661,"enunciado":"Acerca dos aspectos gerais do texto, julgue o item.\n\n\nNo segundo parágrafo, a oração “que é credenciada a um plano de saúde” é uma subordinada substantiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3028202,"enunciado":"Conforme a NORMA CULTA da Língua Portuguesa, assinale a alternativa em que a concordância nominal está correta.","opcoes":["Eles estão quite.","Maria está meio confusa.","Menino e menina disciplinadas.","Há menas professoras na escola.","Ela tem bastante conflitos internos."],"correta":1,"explicacao":"Gabarito: <strong>Maria está meio confusa.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["concordancia"]},{"id":3028208,"enunciado":"Assinale a alternativa em que a concordância verbal está correta.","opcoes":["Faz dez meses que estamos separados.","Fazem dez meses que estamos separados.","Fizeram dez meses que estamos separados.","Vão fazer dez meses que estamos separados.","Vão fazerem dez meses que estamos separados."],"correta":0,"explicacao":"Gabarito: <strong>Faz dez meses que estamos separados.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["concordancia"]},{"id":3046821,"enunciado":"Julgue o item a seguir.\n\nNas regras de concordância verbal da Língua Portuguesa, quando o sujeito é precedido por expressões como cerca de, mais de, menos de e outras que indicam quantidade aproximada, o verbo concorda com o numeral. Como no exemplo: \"Com a medida, cerca de 50 milhões de pessoas serão beneficiadas\".","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3122280,"enunciado":"Com base no texto, julgue o item a seguir. \n\n\n\n\nNa linha 9, a concordância de “havia” está correta por se tratar de menção a tempo transcorrido.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3185044,"enunciado":"Com base na estrutura linguística e no vocabulário empregados no texto, julgue o item seguinte.\n\nNo trecho “a necessidade de se criarem e se implementarem políticas de longo prazo” (linhas 21 e 22), o núcleo do sujeito das formas verbais “criarem” e “implementarem” é “políticas”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3274417,"enunciado":"No que diz respeito à pontuação e à concordância verbal no texto, julgue o item a seguir.\n\n\n\n\nEstaria mantida a correção gramatical do texto caso se inserisse vírgula imediatamente depois do termo “extensa” (linha 21).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3274418,"enunciado":"No que diz respeito à pontuação e à concordância verbal no texto, julgue o item a seguir.\n\n\n\n\nEstaria preservada a correção gramatical do texto caso o trecho “para a conservação da biodiversidade” (linha 24) estivesse destacado entre vírgulas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3274420,"enunciado":"No que diz respeito à pontuação e à concordância verbal no texto, julgue o item a seguir.\n\n\n\n\nA flexão da forma verbal “deve‑se” (linha 23) na terceira pessoa do singular justifica‑se por sua concordância com o termo “quantidade” (linha 22), que é o núcleo do sujeito da oração expressa pela referida forma verbal.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":3781403,"enunciado":"Quanto aos aspectos gramaticais do texto, julgue o item seguinte.\n\n\n\n\nNo trecho “Um tico‑tico (Zonotrichia capensis), muito confundido com o pardal (Passer domesticus), subiu no limoeiro do meu quintal.”, o núcleo do sujeito do verbo “subiu”, na primeira linha do texto, é “pardal”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":4019374,"enunciado":"Com base nos aspectos de pontuação, de concordância verbal e de estrutura do período, julgue o item a seguir.\n\n\n\n\nEm “a impessoalidade, por sua vez, veda favorecimentos indevidos;” a retirada das vírgulas que isolam “por sua vez” manteria a correção gramatical do período.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":4019375,"enunciado":"Com base nos aspectos de pontuação, de concordância verbal e de estrutura do período, julgue o item a seguir.\n\n\n\n\nEm “impropriedades linguísticas ainda que sutis – produzem efeitos”, a forma verbal concorda com o núcleo do sujeito.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":4019376,"enunciado":"Com base nos aspectos de pontuação, de concordância verbal e de estrutura do período, julgue o item a seguir.\n\n\n\n\nNo trecho “a atuação administrativa transcende a mera execução de rotinas burocráticas, pois se vincula diretamente à concretização do interesse público e à observância dos princípios constitucionais que regem a Administração Pública.”, a forma verbal “vincula” poderia ser substituída por está vinculada, sem prejuízo sintático ou semântico.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["concordancia"]},{"id":4019381,"enunciado":"Com base no texto e em seus aspectos linguísticos, julgue o item a seguir, no que concerne ao emprego da crase, à regência verbal e nominal e ao uso de pronomes.\n\n\n\n\nNo trecho “impropriedades linguísticas – ainda que sutis – produzem efeitos jurídicos indesejáveis”, a forma verbal “produzem” poderia ser corretamente substituída por “produz”, mantendo‑se a concordância verbal adequada ao período.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["concordancia","crase"]}];
